ink: 0;\n  line-height: 1;\n  color: var(--stb-color-accent-soft);\n}\n\n.stb-panel__loc-text {\n  min-width: 0;\n  overflow-wrap: break-word;\n  white-space: normal;\n}\n\n.stb-panel__close {\n  position: absolute;\n  right: var(--stb-space-2);\n  top: 50%;\n  transform: translateY(-50%);\n  /* 扩大点击区到 32px（移动端触控），flex 居中图标 */\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 32px;\n  height: 32px;\n  border: none;\n  background: transparent;\n  padding: 0;\n  line-height: 1;\n  color: var(--stb-color-text-dim);\n  cursor: pointer;\n\n  &:hover {\n    color: var(--stb-color-text);\n  }\n}\n\n// ---------- 子 tab 行 ----------\n.stb-panel__tabs {\n  flex-shrink: 0;\n  display: flex;\n  gap: var(--stb-space-1);\n  padding: 0 var(--stb-space-3);\n  border-bottom: 1px solid var(--stb-color-border-soft);\n  overflow-x: auto;\n  scrollbar-width: none;\n\n  &::-webkit-scrollbar {\n    display: none;\n  }\n}\n\n.stb-panel__tab {\n  position: relative;\n  flex-shrink: 0;\n  display: inline-flex;\n  align-items: center;\n  gap: 3px;\n  min-height: 36px;\n  padding: 0 var(--stb-space-2);\n  border: none;\n  background: transparent;\n  color: var(--stb-color-text-dim);\n  font-size: var(--stb-font-size-sm);\n  cursor: pointer;\n}\n\n.stb-panel__tab--on {\n  color: var(--stb-color-accent);\n\n  &::after {\n    content: '';\n    position: absolute;\n    left: var(--stb-space-1);\n    right: var(--stb-space-1);\n    bottom: 0;\n    height: 2px;\n    border-radius: 1px;\n    background: var(--stb-color-accent);\n  }\n}\n\n.stb-panel__count {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  min-width: 16px;\n  height: 16px;\n  padding: 0 4px;\n  border-radius: 999px;\n  background: var(--stb-color-bg-card);\n  font-size: 10px;\n  line-height: 1;\n}\n\n.stb-panel__tab--on .stb-panel__count {\n  background: var(--stb-color-accent);\n  color: #171a24;\n}\n\n// ---------- 内容区 ----------\n.stb-panel__body {\n  flex: 1;\n  min-height: 0;\n  overflow-y: auto;\n  -webkit-overflow-scrolling: touch;\n  padding: var(--stb-space-3) var(--stb-space-4);\n}\n\n.stb-panel__empty {\n  padding: var(--stb-space-5) 0;\n  text-align: center;\n  color: var(--stb-color-text-dim);\n  font-size: var(--stb-font-size-sm);\n}\n"],"sourceRoot":""}]);
